import java.sql.*;
import java.util.*;

public class Main {
    private static final String URL = "jdbc:h2:mem:toko;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1";

    // Membuat tabel produk berisi beberapa data (di laptop, tabel ini sudah ada di MySQL).
    static void siapkan(Connection c) throws SQLException {
        try (Statement st = c.createStatement()) {
            st.execute("CREATE TABLE produk (id INT AUTO_INCREMENT PRIMARY KEY, nama VARCHAR(100) NOT NULL, harga INT NOT NULL, stok INT NOT NULL DEFAULT 0)");
            st.executeUpdate("INSERT INTO produk (nama, harga, stok) VALUES ('Pensil', 3000, 120), ('Buku tulis', 8000, 40), ('Penghapus', 2000, 15), ('Spidol', 9500, 60)");
        }
    }

    public static void main(String[] args) throws SQLException {
        try (Connection c = DriverManager.getConnection(URL, "sa", "")) {
            siapkan(c);
            try (Statement st = c.createStatement();
                 ResultSet rs = st.executeQuery("SELECT nama, harga FROM produk WHERE harga > 5000")) {
                System.out.println("sebelum next");
                while (rs.next()) {
                    System.out.println(rs.getString("nama") + " " + rs.getInt("harga"));
                }
                System.out.println("selesai");
            }
        }
    }
}

